+func ensureConfigureLogin(ctx context.Context, outW, errW io.Writer, deps configureFlowDeps) (*authProfile, error) {
+	target, err := deps.resolveAuth(ctx)
+	if err != nil {
+		return nil, err
+	}
+	if target.token != "" {
+		if err := api.RequireSecureURL(target.coreURL); err != nil {
