+		}
+		if profile, profileErr := deps.fetchProfile(ctx, target.coreURL, target.token); profileErr == nil {
+			return profile, nil
+		} else if !isKeychainTokenRejected(profileErr) {
+			return nil, fmt.Errorf("validate login: %w", profileErr)
+		}
+	}
